// The C++ of Hostkit.Clock, ported from C# (CodeCoreMorph, D-78).
#include "clock.hpp"

#include <time.h>

namespace hostkit {

std::int64_t Clock::nanoseconds() {
    // What the C# does on Linux: clock_gettime(CLOCK_MONOTONIC). Its branch for Windows
    // (QueryPerformanceCounter) isn't this port's, which is built for Linux (D-94).
    timespec now{};
    clock_gettime(CLOCK_MONOTONIC, &now);
    return static_cast<std::int64_t>(now.tv_sec) * 1'000'000'000 + now.tv_nsec;
}

double Clock::milliseconds_since(std::int64_t start) {
    return static_cast<double>(nanoseconds() - start) / 1'000'000.0;
}

}  // namespace hostkit

