// What the C# does on Linux: getpid and strerror from the C library. Its branches for Windows
// (GetCurrentProcessId, FormatMessageW) aren't this port's, which is built for Linux (D-94).
namespace hostkit {

std::int32_t Host::process_id() { return static_cast<std::int32_t>(getpid()); }

std::string Host::error_message(std::int32_t code) {
    const char* message = std::strerror(code);
    std::string text = message != nullptr ? message : "Unknown error " + std::to_string(code);
    // C#'s TrimEnd('\r', '\n', ' ', '.').
    const std::size_t last = text.find_last_not_of("\r\n .");
    text.erase(last == std::string::npos ? 0 : last + 1);
    return text;
}

}  // namespace hostkit

